-- Team Rocket's Ambition (B4a) per-card acquisition probabilities.
-- Sources checked 2026-08-29:
-- https://bulbapedia.bulbagarden.net/wiki/Team_Rocket's_Ambition_(TCG_Pocket)
-- https://pocket.limitlesstcg.com/cards/B4a
-- https://bulbapedia.bulbagarden.net/wiki/Paradox_Drive_(TCG_Pocket)#Offering_rates
-- https://bulbapedia.bulbagarden.net/wiki/Everyday_Wonders_(TCG_Pocket)#Offering_rates
--
-- Definition used by card_pack_odds.pull_probability:
-- P(the card appears at least once in one opened pack).
--
-- Team Rocket's Ambition card lists are published, but the public per-card
-- offering-rate table is not yet filled in on the primary reference pages.
-- These rates use the same single themed-booster slot allocation published
-- for recent comparable sets and apply it to B4a's actual rarity counts.
--
-- Themed-booster pack-type rates used:
--   regular pack:            94.711%
--   regular pack + 1 card:    5.238%
--   rare pack:                0.050%
--
-- In regular packs with a bonus card, Bulbapedia states that the first five
-- cards use the same rates as regular packs without a bonus card. Shiny cards
-- are only available in the sixth-card bonus slot.
--
-- The source publishes per-card rates rounded to three decimal percentage
-- points. These calculations intentionally use those published values.
--
-- Bulbapedia separates one-star and two-star shiny rates from regular
-- one-star and two-star rates. Limitless renders these with the same visible
-- star glyphs in the list view, so this seed applies shiny rates by collector
-- number: B4a-095 through B4a-104 are shiny_1 and B4a-105 through B4a-108
-- are shiny_2.

begin;

insert into public.card_pack_odds (
  pack_id,
  card_id,
  pull_probability,
  source_note,
  verified_at
)
values
  ('b4a-team-rockets-ambition', 'B4a-001', 0.0908044962::numeric, 'Derived from the standard themed-booster Offering Rates structure and the Team Rocket''s Ambition Limitless/Bulbapedia card list; includes regular, regular-plus-bonus, and rare pack paths; cards B4a-095 through B4a-104 use shiny_1 rates and cards B4a-105 through B4a-108 use shiny_2 rates; probability means at least once per opened pack.', date '2026-08-29'),
