on conflict (pack_id, card_id) do update set
  pull_probability = excluded.pull_probability,
  source_note = excluded.source_note,
  verified_at = excluded.verified_at,
  updated_at = now();

-- Stop and roll back if the catalog, pack, or generated odds are incomplete.
do $$
declare
  team_rockets_ambition_cards integer;
  team_rockets_ambition_packs integer;
  team_rockets_ambition_odds integer;
begin
  select count(*)
  into team_rockets_ambition_cards
  from public.cards
  where set_id = 'B4a';

  select count(*)
  into team_rockets_ambition_packs
  from public.packs
  where set_id = 'B4a';

  select count(*)
  into team_rockets_ambition_odds
  from public.card_pack_odds
  where pack_id = 'b4a-team-rockets-ambition';

  if team_rockets_ambition_cards <> 110 then
    raise exception
      'Expected 110 Team Rocket's Ambition cards, found %',
      team_rockets_ambition_cards;
  end if;

  if team_rockets_ambition_packs <> 1 then
    raise exception
      'Expected 1 Team Rocket's Ambition pack, found %',
      team_rockets_ambition_packs;
  end if;

  if team_rockets_ambition_odds <> 110 then
    raise exception
      'Expected 110 Team Rocket's Ambition odds rows, found %',
      team_rockets_ambition_odds;
  end if;
end
$$;

commit;

-- Expected: 110 total records for the Team Rocket's Ambition pack.
select
  cards.rarity,
  count(*) as cards,
  min(card_pack_odds.pull_probability) as min_pull_probability,
  max(card_pack_odds.pull_probability) as max_pull_probability
from public.card_pack_odds
join public.cards
  on cards.id = card_pack_odds.card_id
where card_pack_odds.pack_id = 'b4a-team-rockets-ambition'
group by cards.rarity
order by min(cards.collector_number);
